import axios from 'axios';

const API = axios.create({ baseURL: process.env.REACT_APP_API_URL || '/api' });

API.interceptors.request.use(config => {
  const token = localStorage.getItem('d2d_token');
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

API.interceptors.response.use(res => res, err => {
  if (err.response?.status === 401) {
    localStorage.removeItem('d2d_token');
    localStorage.removeItem('d2d_user');
  }
  return Promise.reject(err);
});

export const authAPI = {
  register: (data) => API.post('/auth/register', data),
  login: (data) => API.post('/auth/login', data),
  getMe: () => API.get('/auth/me'),
  updateProfile: (data) => API.put('/auth/profile', data),
  toggleWishlist: (id) => API.post(`/auth/wishlist/${id}`),
  getWishlist: () => API.get('/auth/wishlist'),
};

export const productAPI = {
  getAll: (params) => API.get('/products', { params }),
  getOne: (id) => API.get(`/products/${id}`),
  create: (data) => API.post('/products', data),
  update: (id, data) => API.put(`/products/${id}`, data),
  delete: (id) => API.delete(`/products/${id}`),
};

export const orderAPI = {
  place: (data) => API.post('/orders', data),
  getMyOrders: () => API.get('/orders/my'),
  getAllOrders: (params) => API.get('/orders', { params }),
  updateStatus: (id, status) => API.put(`/orders/${id}/status`, { status }),
  deleteOrder: (id) => API.delete(`/orders/${id}`),
  getAnalytics: () => API.get('/orders/analytics/summary'),
  exportCSV: () => API.get('/orders/export/csv', { responseType: 'blob' }),
};

export default API;
